// The shirt's shoulder line, from the shirt path of the look. Pure maths (the web reads it from the page: pm.js shoulderLine()).
// Same idea as the web: walk the path, keep the smallest y in bins of 6 kit units. The web samples 901 points by length; here every curve is cut in 48 parts.
export interface ShoulderLine { k0: number; ys: number[]; a: number; e: number; f: number }

function flatten(d: string): number[][] {
  const tok = d.match(/[a-zA-Z]|-?\d*\.?\d+(?:e-?\d+)?/g) || [], pts: number[][] = [];
  let i = 0, cmd = '', x = 0, y = 0, sx = 0, sy = 0, px = 0, py = 0;
  const num = () => +tok[i++], N = 48;
  const curve = (f: (t: number) => number[]) => { for (let s = 1; s <= N; s++) pts.push(f(s / N)); };
  while (i < tok.length) {
    if (/[a-zA-Z]/.test(tok[i])) cmd = tok[i++];
    const rel = cmd === cmd.toLowerCase(), C = cmd.toUpperCase(), ox = rel ? x : 0, oy = rel ? y : 0;
    if (C === 'Z') { x = sx; y = sy; pts.push([x, y]); continue; }
    if (C === 'M') { x = ox + num(); y = oy + num(); sx = x; sy = y; pts.push([x, y]); cmd = rel ? 'l' : 'L'; }
    else if (C === 'L') { x = ox + num(); y = oy + num(); pts.push([x, y]); }
    else if (C === 'H') { x = ox + num(); pts.push([x, y]); }
    else if (C === 'V') { y = oy + num(); pts.push([x, y]); }
    else if (C === 'C' || C === 'S') { const x0 = x, y0 = y; let x1: number, y1: number;
      if (C === 'C') { x1 = ox + num(); y1 = oy + num(); } else { x1 = 2 * x - px; y1 = 2 * y - py; }
      const x2 = ox + num(), y2 = oy + num(), x3 = ox + num(), y3 = oy + num();
      curve(t => { const u = 1 - t; return [u * u * u * x0 + 3 * u * u * t * x1 + 3 * u * t * t * x2 + t * t * t * x3, u * u * u * y0 + 3 * u * u * t * y1 + 3 * u * t * t * y2 + t * t * t * y3]; });
      px = x2; py = y2; x = x3; y = y3; continue; }
    else if (C === 'Q' || C === 'T') { const x0 = x, y0 = y; let x1: number, y1: number;
      if (C === 'Q') { x1 = ox + num(); y1 = oy + num(); } else { x1 = 2 * x - px; y1 = 2 * y - py; }
      const x2 = ox + num(), y2 = oy + num();
      curve(t => { const u = 1 - t; return [u * u * x0 + 2 * u * t * x1 + t * t * x2, u * u * y0 + 2 * u * t * y1 + t * t * y2]; });
      px = x1; py = y1; x = x2; y = y2; continue; }
    else if (C === 'A') { i += 5; x = ox + num(); y = oy + num(); pts.push([x, y]); }
    else i++;
    px = x; py = y;
  }
  return pts;
}

/** zoom + bottomPad = the place of the kit art on the stage (live.js: translate(500 1014) scale(z) translate(-500 -1000)). */
export function makeShoulderLine(d: string, zoom: number, bottomPad: number): ShoulderLine {
  const pts = flatten(d), bins: Record<number, number> = {};
  for (let j = 0; j < pts.length; j++) {       // lines too: walk them in steps of 3 units
    const a = pts[Math.max(0, j - 1)], b = pts[j], n = Math.max(1, Math.ceil(Math.hypot(b[0] - a[0], b[1] - a[1]) / 3));
    for (let s = 1; s <= n; s++) { const qx = a[0] + (b[0] - a[0]) * s / n, qy = a[1] + (b[1] - a[1]) * s / n, k = Math.round(qx / 6); if (bins[k] == null || qy < bins[k]) bins[k] = qy; }
  }
  const ks = Object.keys(bins).map(Number).sort((p, q) => p - q), k0 = ks[0], k1 = ks[ks.length - 1], ys: number[] = [];
  for (let k = k0; k <= k1; k++) { if (bins[k] != null) { ys.push(bins[k]); continue; } let p = k, q = k; while (bins[p] == null) p--; while (bins[q] == null) q++; ys.push(bins[p] + (bins[q] - bins[p]) * (k - p) / (q - p)); }
  return { k0, ys, a: zoom, e: 500 - zoom * 500, f: 1000 + bottomPad - zoom * 1000 };
}

/** y of the shoulder line at stage x (pm.js env.top). Past the ends the line falls with a slope of 0.35. */
export function shoulderTop(S: ShoulderLine, x: number): number {
  'worklet';
  const u = (x - S.e) / S.a / 6, k1 = S.k0 + S.ys.length - 1; let yl: number;
  if (u <= S.k0) yl = S.ys[0] + (S.k0 - u) * 6 * .35;
  else if (u >= k1) yl = S.ys[S.ys.length - 1] + (u - k1) * 6 * .35;
  else { const a = Math.floor(u), b = Math.ceil(u), ya = S.ys[a - S.k0], yb = S.ys[b - S.k0]; yl = a === b ? ya : ya + (yb - ya) * (u - a); }
  return S.a * yl + S.f;
}

export interface Strip { on: boolean; d: string; x1: number; y1: number; x2: number; y2: number }

export interface HandFrame {
  art: string;
  show: boolean;
  x: number; y: number;                    // wrist joint on the stage
  rotate: number;                          // degrees, + = clockwise
  skewX: number;                           // tan of the finger trail
  scaleX: number; scaleY: number;          // scaleX < 0 = mirrored
  originX: number; originY: number;        // the art point that sits on (x, y), as a translate
  matrix: number[];                        // the same transform as [a, b, c, d, e, f]
  transform: string;                       // the same transform as SVG text (equal to the web studio)
  clip: string;                            // path: the hand is cut at the cuff line
  sleeve: string;                          // path: the rigid sleeve (cuff + tube + round cap)
  cuff: string;                            // path: the cuff band (stroke, cut to the sleeve)
  seam: Strip;                             // line where the sleeve goes onto the shirt (gradient ends)
  shadow: Strip;                           // contact shadow strip beside the seam (gradient ends)
  armShadow: { on: boolean; matrix: number[] }; // contact shadow of the arm (pm.js SHD, Palms up and Wave hello): the hand drawing as one colour, this matrix, cut to the regions (FrameState.shadowM)
  plush?: number[];                        // heart hands only: matrix of the plush heart inside the hand drawing (art units); it grows and rises with the pulse
}

export interface Beat { up: number; spread: number; dy: number; dfa: number; dha: number; wrist: boolean; sk: number; tilt: number; ny: number; face: boolean; pop: number; plush: number }

export interface PrepHand {
  art: string; artW: number; artH: number; ox: number; oy: number; wdeg: number; cutHalf: number; m: number; size: number; sl: number; sgn: number;
  rigid: boolean; enX: number; enY: number;      // rigid = arm with a sleeve that rises from below (all but the heart hands); en = the rig's own slide in (heart hands)
  atX: number; atY: number; angle: number; wristX: number; wristY: number; fa: number; bend: number;
  Sx: number; Sy: number; L: number; side: number; dvx: number; dvy: number; sI: number;      // pm.js RIG
}

export interface Posed { Wx: number; Wy: number; R: number; sk: number; k: number; dx: number; dy: number; w: number }   // k includes the pop of the beat; w (sleeve width) does not

/** hands-rig.js swing(): h = hand angle, f = forearm angle, env, ph. Returned as an array (no object per call on the hot path is not needed; kept simple). */
export function swing(ms: number): number[] {
  'worklet';
  if (ms < WAVE.s0) return [0, 0, 0, 0];
  const u = seg(ms, WAVE.s0, WAVE.s1), ph = 2 * Math.PI * WAVE.f * (ms - WAVE.s0) / 1000;
  const env = Math.sin(Math.PI / 2 * Math.min(1, u / WAVE_X.envIn)) * (1 - WAVE_X.decay * u) * (1 - io(seg(ms, WAVE.s1 - WAVE_X.fadeMs, WAVE.s1)));
  return [WAVE.A * env * Math.sin(ph), WAVE.F * env * Math.sin(ph + WAVE.lead), env, ph];
}

/** hands-rig.js AT.wave2. */
export function beatWave(ms: number): Beat {
  'worklet';
  const T = WAVE.T, c = clamp(ms, 0, T), X = WAVE_X, lin = seg(c, 0, WAVE.lift), lift = outBack(Math.pow(lin, X.liftPow), X.liftBack), drop = io(seg(c, T - X.dropMs, T)), s = swing(c), sd = swing(c - WAVE.lag);
  const drag = X.drag0 * Math.pow(1 - lin, 2) - X.dragOut * io(seg(c, T - X.dragFrom, T - X.dragTo));
  return { up: lift * (1 - drop), spread: 0, dy: 0, dfa: s[1] - X.armBack * (1 - lift) * (1 - drop) + X.armDrop * drop, dha: s[0] + drag, wrist: true, sk: Math.tan((s[0] - sd[0]) * X.skewK * D),
    tilt: X.tilt * io(seg(c, X.tiltIn[0], X.tiltIn[1])) * (1 - io(seg(c, T - X.tiltOut[0], T - X.tiltOut[1]))) + X.sway * s[2] * Math.sin(s[3] - X.swayPhase), ny: X.nod * bump(seg(c, X.nodSeg[0], X.nodSeg[1])), face: c > X.faceIn && c < T - X.faceOut, pop: 1, plush: 0 };
}

/** hands-rig.js AT.heart3 + the plush pulse of pm.js handMoment. plush = 0..1, how far the plush is into its pulse (twice, 340 ms each). */
export function beatHeart(ms: number): Beat {
  'worklet';
  const C = HEART, T = POSES.heart3.dur, c = clamp(ms, 0, T), b = bump(seg(c, C.pulse[0], C.pulse[1])), pl = ms >= PLUSH.pulseFrom && ms <= PLUSH.pulseTo ? Math.max(0, Math.sin(2 * Math.PI * (ms - PLUSH.pulseFrom) / PLUSH.period)) : 0;
  return { up: up2(ms, T, UP2.i, UP2.o), spread: 0, dy: C.dy * b, dfa: 0, dha: 0, wrist: false, sk: 0, tilt: C.tilt * io(seg(c, C.tiltIn[0], C.tiltIn[1])) * (1 - io(seg(c, C.tiltOut[0], C.tiltOut[1]))),
    ny: C.ny * io(seg(c, C.nyIn[0], C.nyIn[1])) * (1 - io(seg(c, C.nyOut[0], C.nyOut[1]))), face: c > MOMENTS['h-heart'].faceIn && c < MOMENTS['h-heart'].faceOff, pop: 1 + C.pop * b, plush: pl };
}

/** hands-rig.js AT.chin: Hand at the chin. The hand turns a little with the nod (rot goes into the hand angle, not into the wrist swing). */
export function beatChin(ms: number): Beat {
  'worklet';
  const C = CHIN, T = POSES.chin.dur, c = clamp(ms, 0, T), n = seg(c, C.seg[0], C.seg[1]), nod = C.nod * Math.sin(2 * Math.PI * C.freq * n) * bump(n);
  return { up: up2(ms, T, UP2.i, UP2.o), spread: 0, dy: nod * C.dyK, dfa: 0, dha: C.rot * Math.sin(2 * Math.PI * C.freq * n - C.rotPh) * bump(n), wrist: false, sk: 0,
    tilt: C.tilt * io(seg(c, C.tiltIn[0], C.tiltIn[1])) * (1 - io(seg(c, C.tiltOut[0], C.tiltOut[1]))), ny: C.dip * bump(seg(c, C.dipSeg[0], C.dipSeg[1])) + nod,
    face: c > MOMENTS['h-chin'].faceIn && c < MOMENTS['h-chin'].faceOff, pop: 1, plush: 0 };
}

/** hands-rig.js frame(): where the wrist is, the hand angle, the forearm direction and the sleeve width. enter = [0,0] (pm.js P2). */
export function poseHand(h: PrepHand, A: boolean, b: Beat): Posed {
  'worklet';
  const k0 = h.size / h.artH, k = k0 * b.pop, off = 1 - b.up; let Wx: number, Wy: number, R: number, sk: number, dx: number, dy: number;
  if (A) { Wx = h.atX + h.enX * off - b.spread * h.sgn * PALMS.spreadX; Wy = h.atY + h.enY * off + b.dy; R = h.angle - b.spread * h.sgn; sk = 0;
    const x = Math.cos(h.wdeg * D) * h.m, y = Math.sin(h.wdeg * D), c = Math.cos(R * D), s = Math.sin(R * D); dx = x * c - y * s; dy = x * s + y * c; }
  else { const L = ARM.forearm, Ex = h.wristX - L * Math.sin(h.fa * D), Ey = h.wristY + L * Math.cos(h.fa * D) + b.dy, fa = h.fa + b.dfa, dm = h.m < 0 ? 180 - h.wdeg : h.wdeg;
    Wx = Ex + L * Math.sin(fa * D); Wy = Ey - L * Math.cos(fa * D); R = (90 + fa) - dm + h.bend + b.dha; sk = b.sk; dx = -Math.sin(fa * D); dy = Math.cos(fa * D); }
  const cut = h.cutHalf * k0, w = Math.max(h.sl * h.artW * k0, 2 * cut * ARM.cutMin + ARM.cutPad);
  return { Wx, Wy, R, sk, k, dx, dy, w };
}

export const NO_STRIP: Strip = { on: false, d: '', x1: 0, y1: 0, x2: 0, y2: 0 };

export const NO_ARM = { on: false, matrix: [1, 0, 0, 1, 0, 0] };

export const BIG_CLIP = 'M-9999 -9999H9999V9999H-9999Z';

export function heartFrame(h: PrepHand, p: Posed, b: Beat, show: boolean): HandFrame {
  'worklet';
  const x = p.Wx, y = p.Wy, rotate = p.R, scaleX = p.k * h.m, scaleY = p.k, rc = Math.cos(rotate * D), rs = Math.sin(rotate * D);
  const ma = rc * scaleX, mb = rs * scaleX, mc = rc * p.sk * scaleY - rs * scaleY, md = rs * p.sk * scaleY + rc * scaleY;
  const matrix = [ma, mb, mc, md, x + ma * h.ox + mc * h.oy, y + mb * h.ox + md * h.oy];
  const transform = 'translate(' + x.toFixed(2) + ' ' + y.toFixed(2) + ') rotate(' + rotate.toFixed(3) + ') matrix(1 0 ' + p.sk.toFixed(4) + ' 1 0 0) scale(' + scaleX.toFixed(5) + ' ' + scaleY.toFixed(5) + ') translate(' + h.ox + ' ' + h.oy + ')';
  const g = 1 + PLUSH.grow * b.plush, rise = -PLUSH.rise * b.plush;    // the studio text: translate(c) scale(g) translate(-c) translate(0 rise): the rise is inside the scale
  return { art: h.art, show, x, y, rotate, skewX: p.sk, scaleX, scaleY, originX: h.ox, originY: h.oy, matrix, transform, clip: BIG_CLIP, sleeve: '', cuff: '', seam: NO_STRIP, shadow: NO_STRIP, armShadow: NO_ARM,
    plush: [g, 0, 0, g, PLUSH.cx * (1 - g), PLUSH.cy * (1 - g) + g * rise] };
}

/** pm.js handMoment, the part inside the frame loop: the rigid arm that rises from below, the hand cut, the sleeve, the cuff, the seam and its shadow strip. */
export function handFrame(h: PrepHand, A: boolean, b: Beat, show: boolean, S: ShoulderLine, AS: { dx: number; dy: number } | null): HandFrame {
  'worklet';
  const p = poseHand(h, A, b);
  if (!h.rigid) return heartFrame(h, p, b, show);
  const SU = A ? ARM.sleeveUpA : ARM.sleeveUpB, off = 1 - b.up, th = h.side * ARM.riseTilt * off, tvx = h.dvx * ARM.riseDist * off, tvy = h.dvy * ARM.riseDist * off;
  const cs = Math.cos(th * D), sn = Math.sin(th * D);
  const Jqx = p.Wx - p.dx * SU, Jqy = p.Wy - p.dy * SU;                                         // the wrist joint at the cuff
  const qx = h.Sx + (Jqx - h.Sx) * cs - (Jqy - h.Sy) * sn + tvx, qy = h.Sy + (Jqx - h.Sx) * sn + (Jqy - h.Sy) * cs + tvy;
  const gh = th * ARM.handTiltShare, gp = gh + (b.wrist ? b.dha : 0), gc = Math.cos(gp * D), gs = Math.sin(gp * D), w0x = p.Wx - Jqx, w0y = p.Wy - Jqy;
  const x = qx + w0x * gc - w0y * gs, y = qy + w0x * gs + w0y * gc, rotate = p.R + gh, scaleX = p.k * h.m, scaleY = p.k;
  const rc = Math.cos(rotate * D), rs = Math.sin(rotate * D), ma = rc * scaleX, mb = rs * scaleX, mc = rc * p.sk * scaleY - rs * scaleY, md = rs * p.sk * scaleY + rc * scaleY;
  const matrix = [ma, mb, mc, md, x + ma * h.ox + mc * h.oy, y + mb * h.ox + md * h.oy];
  const transform = 'translate(' + x.toFixed(2) + ' ' + y.toFixed(2) + ') rotate(' + rotate.toFixed(3) + ') matrix(1 0 ' + p.sk.toFixed(4) + ' 1 0 0) scale(' + scaleX.toFixed(5) + ' ' + scaleY.toFixed(5) + ') translate(' + h.ox + ' ' + h.oy + ')';
  const base = { art: h.art, show, x, y, rotate, skewX: p.sk, scaleX, scaleY, originX: h.ox, originY: h.oy, matrix, transform };
  if (!show) return { ...base, clip: '', sleeve: '', cuff: '', seam: NO_STRIP, shadow: NO_STRIP, armShadow: NO_ARM };
  const dx = p.dx * cs - p.dy * sn, dy = p.dx * sn + p.dy * cs, nx = -dy, ny = dx;
  let armShadow = NO_ARM;       // pm.js SHD: the hand drawing as a silhouette, moved 4 toward the body (side of the sleeve point) and 11 down
  if (AS) { const side = +(qx + dx * SU).toFixed(1) < 500 ? 1 : -1; armShadow = { on: true, matrix: [matrix[0], matrix[1], matrix[2], matrix[3], matrix[4] + AS.dx * side, matrix[5] + AS.dy] }; }
  const T2 = (ax: number, ay: number) => ax.toFixed(1) + ' ' + ay.toFixed(1);
  const c4 = (al: number, ac: number) => T2(qx + dx * al - dy * ac, qy + dy * al + dx * ac);
  const clip = 'M' + c4(ARM.clipAhead, -900) + 'L' + c4(ARM.clipAhead, 900) + 'L' + c4(-1500, 900) + 'L' + c4(-1500, -900) + 'Z';
  const hw0 = Math.max(ARM.cuffMin, p.w * ARM.cuffScaleW / 2 - ARM.cuffInset), hw = A ? hw0 : ARM.wideB * hw0, wd = A ? ARM.widenA : ARM.widenB, sI = h.sI, sO = -sI, Le = h.L, hwe = hw * ARM.capK;
  const Px = (al: number, ac: number) => qx + dx * al + nx * ac * (1 + wd * Math.max(0, al - ARM.widenFrom));
  const Py = (al: number, ac: number) => qy + dy * al + ny * ac * (1 + wd * Math.max(0, al - ARM.widenFrom));
  const Pax = Px(0, sI * hw), Pay = Py(0, sI * hw), Pbx = Px(14, sO * hw), Pby = Py(14, sO * hw), Cmx = Px(-22, 0), Cmy = Py(-22, 0);
  const Cax = Pax + (Cmx - Pax) * .3, Cay = Pay + (Cmy - Pay) * .3, Cbx = Pbx + (Cmx - Pbx) * .3, Cby = Pby + (Cmy - Pby) * .3;
  const I1x = Px(14, sI * hw), I1y = Py(14, sI * hw), O1x = Px(28, sO * hw), O1y = Py(28, sO * hw);
  const sleeve = 'M' + T2(I1x, I1y) + 'Q' + T2(Pax, Pay) + ' ' + T2(Cax, Cay) + 'Q' + T2(Cmx, Cmy) + ' ' + T2(Cbx, Cby) + 'Q' + T2(Pbx, Pby) + ' ' + T2(O1x, O1y)
    + 'L' + T2(Px(Le, sO * hw), Py(Le, sO * hw)) + 'C' + T2(Px(Le + hwe, sO * hw), Py(Le + hwe, sO * hw)) + ' ' + T2(Px(Le + hwe, sI * hw), Py(Le + hwe, sI * hw)) + ' ' + T2(Px(Le, sI * hw), Py(Le, sI * hw)) + 'Z';
  const k6x = dx * ARM.cuffShift, k6y = dy * ARM.cuffShift;
  const cuff = 'M' + T2(I1x + k6x, I1y + k6y) + 'Q' + T2(Pax + k6x, Pay + k6y) + ' ' + T2(Cax + k6x, Cay + k6y) + 'Q' + T2(Cmx + k6x, Cmy + k6y) + ' ' + T2(Cbx + k6x, Cby + k6y) + 'Q' + T2(Pbx + k6x, Pby + k6y) + ' ' + T2(O1x + k6x, O1y + k6y);
  let ac = -1;                                                                                   // where the inner edge of the sleeve goes onto the shirt
  for (let al = ARM.shoulderFrom; al <= Le; al += ARM.shoulderStep) { if (Py(al, sI * hw) >= shoulderTop(S, Px(al, sI * hw)) + ARM.shoulderPad) { ac = al; break; } }
  let seam = NO_STRIP, shadow = NO_STRIP;
  if (ac >= 0) {
    const a0x = Px(ac - ARM.seamBack, sI * hw), a0y = Py(ac - ARM.seamBack, sI * hw), a1x = Px(ac + ARM.seamLen, sI * hw), a1y = Py(ac + ARM.seamLen, sI * hw);
    seam = { on: true, d: 'M' + T2(a0x, a0y) + 'L' + T2(a1x, a1y), x1: +a0x.toFixed(1), y1: +a0y.toFixed(1), x2: +a1x.toFixed(1), y2: +a1y.toFixed(1) };
    const e = (al: number, o: number) => T2(Px(al, sI * (hw + o)), Py(al, sI * (hw + o))), i0 = ARM.shadowIn, o0 = ARM.shadowOut;
    shadow = { on: true, d: 'M' + e(ac - ARM.shadowBack, i0) + 'L' + e(Le, i0) + 'L' + e(Le, o0) + 'L' + e(ac - ARM.shadowBack, o0) + 'Z',
      x1: +Px(ac, sI * (hw + i0)).toFixed(1), y1: +Py(ac, sI * (hw + i0)).toFixed(1), x2: +Px(ac, sI * (hw + o0)).toFixed(1), y2: +Py(ac, sI * (hw + o0)).toFixed(1) };
  }
  return { ...base, clip, sleeve, cuff, seam, shadow, armShadow };
}
